using System;
using System.Diagnostics;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop: save the world over RCON (SaveWorld), ask the server to exit (DoExit), then wait until the
// process is gone so the panel's stop doesn't kill it while it is still writing the save.
var pid = ThisService.ProcessId;
var port = ThisService.RconPort;
string password = ThisService.Variables.Parse<string>("RconPassword", "") ?? "";
const int maxWaitSeconds = 300;

bool IsRunning(int id)
{
    try { using (var p = Process.GetProcessById(id)) return !p.HasExited; }
    catch (ArgumentException) { return false; }
    catch (InvalidOperationException) { return false; }
}

void ReadExactly(NetworkStream s, byte[] buffer, int count)
{
    int read = 0;
    while (read < count)
    {
        int n = s.Read(buffer, read, count - read);
        if (n <= 0) throw new IOException("the server closed the RCON connection");
        read += n;
    }
}

void Send(NetworkStream s, int id, int type, string body)
{
    byte[] text = Encoding.UTF8.GetBytes(body);
    byte[] packet = new byte[14 + text.Length];
    BitConverter.GetBytes(10 + text.Length).CopyTo(packet, 0);
    BitConverter.GetBytes(id).CopyTo(packet, 4);
    BitConverter.GetBytes(type).CopyTo(packet, 8);
    text.CopyTo(packet, 12);
    s.Write(packet, 0, packet.Length);
}

// Reads packets until one answers request `id` (or, for the login, until the auth reply arrives).
(int Id, string Body) Receive(NetworkStream s, int id, bool auth)
{
    while (true)
    {
        byte[] header = new byte[4];
        ReadExactly(s, header, 4);
        int size = BitConverter.ToInt32(header, 0);
        if (size < 10 || size > 1 << 20) throw new IOException("unexpected RCON packet size " + size);
        byte[] data = new byte[size];
        ReadExactly(s, data, size);
        int replyId = BitConverter.ToInt32(data, 0);
        int type = BitConverter.ToInt32(data, 4);
        string body = Encoding.UTF8.GetString(data, 8, size - 10);
        if (auth ? type == 2 : replyId == id) return (replyId, body);
    }
}

// DoExit saves the world once more and then the process tears down, which can take minutes on a busy host.
// The log shows "Closing by request" followed by "World Save Complete" once that last save is on disk.
string logFile = Path.Combine(ThisService.RootDirectory, "ShooterGame", "Saved", "Logs", "ShooterGame.log");
long logStart = 0;

long LogLength()
{
    try { return new FileInfo(logFile).Length; } catch { return 0; }
}

bool FinalSaveDone()
{
    try
    {
        using (var fs = new FileStream(logFile, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
        {
            if (fs.Length <= logStart) return false;
            fs.Seek(logStart, SeekOrigin.Begin);
            string text = new StreamReader(fs).ReadToEnd();
            int closing = text.IndexOf("Closing by request", StringComparison.Ordinal);
            return closing >= 0 && text.IndexOf("World Save Complete", closing, StringComparison.Ordinal) >= 0;
        }
    }
    catch { return false; }
}

if (pid == null || pid <= 0 || !IsRunning(pid.Value))
{
    ScriptConsole.WriteLine((object)"The server is not running; nothing to save.");
    return;
}
if (password.Length == 0)
{
    ScriptConsole.WriteLine((object)"No admin (RCON) password is set, so the world can't be saved before the stop.");
    return;
}

try
{
    using (var client = new TcpClient())
    {
        var connect = client.ConnectAsync("127.0.0.1", port);
        if (await Task.WhenAny(connect, Task.Delay(5000)) != connect)
            throw new Exception("timed out connecting to RCON port " + port);
        await connect;
        var stream = client.GetStream();
        stream.ReadTimeout = 10000;

        Send(stream, 1, 3, password);
        if (Receive(stream, 1, true).Id == -1)
            throw new Exception("the admin (RCON) password was rejected");

        stream.ReadTimeout = 180000; // a large world can take a while to write
        Send(stream, 2, 2, "SaveWorld");
        ScriptConsole.WriteLine((object)("SaveWorld: " + Receive(stream, 2, false).Body.Trim()));

        stream.ReadTimeout = 10000;
        logStart = LogLength();
        Send(stream, 3, 2, "DoExit");
        try { ScriptConsole.WriteLine((object)("DoExit: " + Receive(stream, 3, false).Body.Trim())); }
        catch (IOException) { ScriptConsole.WriteLine((object)"DoExit: sent"); }
    }
}
catch (Exception ex)
{
    // Still loading, or RCON is not reachable: the panel's own stop takes over.
    ScriptConsole.WriteLine((object)("Could not save over RCON (" + ex.Message + "); the server is stopped without saving."));
    return;
}

const int exitGraceSeconds = 20;
int savedAt = -1;
for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!IsRunning(pid.Value))
    {
        ScriptConsole.WriteLine((object)("The world was saved and the server exited after " + second + " s."));
        return;
    }
    if (savedAt < 0 && FinalSaveDone())
        savedAt = second;
    if (savedAt >= 0 && second - savedAt >= exitGraceSeconds)
    {
        ScriptConsole.WriteLine((object)("The world was saved after " + savedAt + " s; the server is still shutting down, so the panel stops it now."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));

