using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// ARK: Survival Ascended downloads and loads the CurseForge mods listed in -mods=id1,id2 (the Mods variable)
// by itself when it starts. Add this mod to the list and re-derive the command line.
string modId = Convert.ToString(Dynamic.ModId).Trim();

var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
var current = service.Variables ?? new TCAdminVars();
var mods = current.Parse<string>("Mods", string.Empty)
    .Split(new[] { ',', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries)
    .Select(x => x.Trim()).Where(x => x.Length > 0).ToList();

if (mods.Contains(modId))
{
    ScriptConsole.WriteLine((object)$"Mod {modId} is already in the mod list.");
}
else
{
    mods.Add(modId);
    var updated = new TCAdminVars();
    foreach (var pair in current) updated[pair.Key] = pair.Value;
    updated["Mods"] = string.Join(",", mods);
    service.Variables = updated;
    GameServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
    await GameServiceManager.SaveChangesAsync(ThisCancellationToken);
    ScriptConsole.WriteLine((object)("Mods=" + updated["Mods"]));
}

var refresh = await ServiceManager.RefreshActiveCommandLine(null, ThisService.ServiceId);
ScriptConsole.WriteLine((object)(string.IsNullOrEmpty(refresh.Error) ? "Command line updated." : "Command line not updated: " + refresh.Error));
