using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// ARK: Survival Ascended lists its servers in Epic Online Services, but the public client the game's server
// browser uses can no longer search sessions from outside the game (Epic answers 403 "missing
// matchmaking:findSessions"). So the server is queried over its own RCON port instead: a successful login
// means it is up, and ListPlayers gives the players. Name, map and cluster come from the command line.
string address = Globals.GetValue<string>("Address");
if (string.IsNullOrEmpty(address)) address = string.IsNullOrEmpty(ThisService.IPAddress) ? "127.0.0.1" : ThisService.IPAddress;
int port = ThisService.RconPort;
string password = ThisService.Variables.Parse<string>("RconPassword", "") ?? "";
string commandLine = ThisService.Commandline ?? "";

void ReadExactly(NetworkStream s, byte[] buffer, int count)
{
    int read = 0;
    while (read < count)
    {
        int n = s.Read(buffer, read, count - read);
        if (n <= 0) throw new IOException("the server closed the RCON connection");
        read += n;
    }
}

